import{_ as t,c as o,o as s,ag as i}from"./chunks/framework.bCALENAD.js";const p=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting.md","filePath":"en/troubleshooting.md","lastUpdated":1720813934000}'),n={name:"troubleshooting.md"};function l(a,e,r,d,c,u){return s(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>In this guide, you will learn how to fix known errors with this service.</p><div class="danger custom-block"><p class="custom-block-title">Could not open the database file. Maybe it is damaged?</p><p>There can be several solutions to this error. Just work through all possibilities and your problem should be solved. 😃</p><ol><li><p><strong>Set the required permissions</strong><br> To set the permissions, enter the command <code>chmod 700 /opt/myspeed</code>. (Replace /opt/myspeed with your installation location).</p></li><li><p><strong>Install the build essentials</strong><br> It is currently possible that the error occurs because the <code>build-essential</code> package is not installed. Simply reinstall it with the command <code>sudo apt-get install build-essential</code>.</p></li><li><p><strong>Perform a new installation of the modules</strong><br> First, enter the command <code>rm -R node_modules</code> in the installation folder to delete the modules and then reinstall them with <code>npm install</code>.</p></li></ol></div><div class="danger custom-block"><p class="custom-block-title">This MySpeed instance is currently in development mode</p><p>This is not really an error, just a backup to use the tool only in production environments. Set the environment variable <code>NODE_ENV</code> to the value <code>production</code>.<br> On Linux, you can do this with <code>export NODE_ENV=production</code> and on Windows in the PowerShell with <code>$env:NODE_ENV=&quot;production&quot;</code>.<br> Also, read the <a href="./setup/linux">guide for 24/7 installation</a> if you plan to run MySpeed in the background and start it automatically at system startup.</p></div>',4)])])}const m=t(n,[["render",l]]);export{p as __pageData,m as default};
